size_t count = 100;
if (count > SIZE_MAX / sizeof(int)) {
    return EXIT_FAILURE;
}
int *values = malloc(count * sizeof *values);
if (values == NULL) {
    return EXIT_FAILURE;
}
/* use values */
free(values);
values = NULL;

size_t new_capacity = capacity * 2;
int *tmp = realloc(values, new_capacity * sizeof *values);
if (tmp == NULL) {
    /* values هنوز معتبر است */
    free(values);
    return EXIT_FAILURE;
}
values = tmp;
capacity = new_capacity;

void destroy_vector(struct Vector *v) {
    if (v == NULL) return;
    free(v->data);
    v->data = NULL;
    v->size = 0;
    v->capacity = 0;
}
